-- Module: stock. Canonical securities shared by all users (never duplicated per user).

CREATE TABLE stocks
(
    id           UUID PRIMARY KEY,
    symbol       VARCHAR(20)  NOT NULL,
    company_name VARCHAR(200) NOT NULL,
    -- Former or colloquial names that users search for (e.g. "Facebook" for Meta Platforms).
    aliases      VARCHAR(255),
    exchange     VARCHAR(40)  NOT NULL,
    mic          VARCHAR(10)  NOT NULL,
    currency     VARCHAR(3)   NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
    country      VARCHAR(2)   NOT NULL CHECK (country ~ '^[A-Z]{2}$'),
    sector       VARCHAR(80),
    industry     VARCHAR(120),
    asset_type   VARCHAR(20)  NOT NULL,
    active       BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at   TIMESTAMPTZ  NOT NULL,
    updated_at   TIMESTAMPTZ  NOT NULL,
    version      BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT uq_stocks_symbol UNIQUE (symbol),
    CONSTRAINT ck_stocks_symbol_normalized CHECK (symbol = upper(btrim(symbol))),
    CONSTRAINT ck_stocks_asset_type CHECK (asset_type IN ('COMMON_STOCK', 'ADR', 'ETF'))
);

CREATE INDEX ix_stocks_sector ON stocks (sector) WHERE active;

